-- M3C-PERSONA-002 — Request-path gate, row level security policies, grants.
--
-- STATUS: PROPOSAL. Not executed. Not approved for execution. Supersedes
-- milestone-3a/004-persona-rls-and-grants.sql.
--
-- Purpose and scope
--   Install folioone.persona_write_rpc_context() (the request-path/method write
--   gate), the owner policies for the five Persona tables, and the narrow
--   column-level grants the SECURITY INVOKER functions in 003 need. After this
--   file, authenticated users can SELECT only their own rows and can write ONLY
--   inside a POST to one of the nine approved /rpc/persona_* endpoints.
--
-- Differences from milestone-3a/004 (proposed resolutions; see the decision doc):
--   P-4  The allowlist names exactly the nine functions the application uses
--        (create_with_configuration, update_metadata,
--        apply_profile_field_changes, upsert_section, reorder_sections,
--        set_default, set_lifecycle, duplicate, delete). persona_create,
--        persona_update_profile_field and persona_delete_section are dropped:
--        nothing calls them, and every allowlisted endpoint widens the write
--        surface.
--   P-5  persona_sections has no DELETE policy or grant (no function deletes a
--        section; rows are removed only by the owner-run ON DELETE CASCADE).
--   P-6  personas.position is not updatable (no function changes it).
--   P-3  Preconditions are enforced and the outcome is asserted before COMMIT.
--
-- Evidence behind the gate: the hosted request-path diagnostic
-- (docs/sql/milestone-3a/diagnostics, executed 2026-11-09 against the
-- development project) observed request.method = 'POST' and request.path =
-- '/rpc/<function>' with no prefix, spoof attempts never opened the gate, and
-- direct table writes were rejected. The diagnostic used mirror objects, so the
-- real paths are covered only by construction; the hosted tests in
-- tests/hosted/persona-persistence.hosted.ts verify the real names.
-- The gate is an INTEGRITY control (it forces writes through the version and
-- revision logic). Tenant ISOLATION is the owner predicate and does not depend
-- on it. Never loosen the exact-equality match (no LIKE, prefix or regex).
--
-- Preconditions (enforced; failure aborts and creates nothing)
--   - 001 executed: five tables exist, RLS enabled AND forced, no non-owner
--     privileges, no policies.
--   - persona_write_rpc_context() does not exist.
--   - authenticated can execute auth.uid().
--   - No zz_diag_m3a_* objects remain (diagnostic cleaned up).
-- Execution order: 2 of 3. Run in the same session as 001 and 003.
-- Repeatability: ONE-TIME. A rerun aborts in the precondition block.
-- Expected outcome: 16 policies (personas 4, persona_sections 3,
--   persona_profile_field_selections 3, persona_profile_overrides 4,
--   persona_revisions 2); column-level INSERT/UPDATE only; no anon, PUBLIC or
--   service_role privileges. Verification: verify-catalog.sql, sections 1-3.
-- Rollback / recovery: see rollback.sql (drop 003 functions first).

BEGIN;

DO $preflight$
BEGIN
  IF session_user <> 'postgres' OR current_user <> 'postgres' THEN
    RAISE EXCEPTION 'Run as postgres in the SQL Editor';
  END IF;
  IF (SELECT count(*) FROM pg_class AS c JOIN pg_namespace AS n ON n.oid = c.relnamespace
      WHERE n.nspname = 'folioone' AND c.relkind = 'r'
        AND c.relname IN ('personas', 'persona_sections',
          'persona_profile_field_selections', 'persona_profile_overrides',
          'persona_revisions')
        AND c.relrowsecurity AND c.relforcerowsecurity) <> 5 THEN
    RAISE EXCEPTION '001 must be executed first: five Persona tables with RLS enabled and forced';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'folioone'
             AND tablename IN ('personas', 'persona_sections',
               'persona_profile_field_selections', 'persona_profile_overrides',
               'persona_revisions')) THEN
    RAISE EXCEPTION 'Persona policies already exist; this file is one-time';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_proc AS p JOIN pg_namespace AS n ON n.oid = p.pronamespace
             WHERE n.nspname = 'folioone'
               AND (p.proname = 'persona_write_rpc_context'
                    OR p.proname LIKE 'zz\_diag\_m3a\_%')) THEN
    RAISE EXCEPTION 'persona_write_rpc_context() or zz_diag_m3a_* objects already exist';
  END IF;
  IF to_regclass('folioone.zz_diag_m3a_events') IS NOT NULL
     OR to_regclass('folioone.zz_diag_m3a_direct') IS NOT NULL THEN
    RAISE EXCEPTION 'Diagnostic tables still exist; run diag-003-cleanup.sql first';
  END IF;
  IF NOT has_function_privilege('authenticated', 'auth.uid()', 'EXECUTE') THEN
    RAISE EXCEPTION 'authenticated must be able to execute auth.uid()';
  END IF;
END;
$preflight$;

-- 1. Request-context gate ------------------------------------------------------
-- True only for a POST whose PostgREST request path is exactly one approved
-- Persona mutation endpoint. Missing or empty settings fail closed (false).
-- Read-only; its own path is deliberately not on the list.
CREATE FUNCTION folioone.persona_write_rpc_context()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY INVOKER
SET search_path = ''
AS $$
  SELECT COALESCE(
    current_setting('request.method', true) = 'POST'
    AND current_setting('request.path', true) = ANY (ARRAY[
      '/rpc/persona_create_with_configuration',
      '/rpc/persona_update_metadata',
      '/rpc/persona_apply_profile_field_changes',
      '/rpc/persona_upsert_section',
      '/rpc/persona_reorder_sections',
      '/rpc/persona_set_default',
      '/rpc/persona_set_lifecycle',
      '/rpc/persona_duplicate',
      '/rpc/persona_delete'
    ]),
    false
  );
$$;
REVOKE ALL ON FUNCTION folioone.persona_write_rpc_context() FROM PUBLIC, anon, service_role;
GRANT EXECUTE ON FUNCTION folioone.persona_write_rpc_context() TO authenticated;

-- 2. Policies ------------------------------------------------------------------
-- SELECT: owner only (no gate). INSERT/UPDATE/DELETE: owner AND gate. UPDATE and
-- DELETE carry the gate in USING, so SELECT ... FOR UPDATE/SHARE row locks (which
-- evaluate UPDATE USING) also require an approved RPC request.

-- personas
CREATE POLICY personas_select_own ON folioone.personas
  FOR SELECT TO authenticated USING (account_id = (SELECT auth.uid()));
CREATE POLICY personas_insert_rpc_own ON folioone.personas
  FOR INSERT TO authenticated
  WITH CHECK (account_id = (SELECT auth.uid())
              AND (SELECT folioone.persona_write_rpc_context()));
CREATE POLICY personas_update_rpc_own ON folioone.personas
  FOR UPDATE TO authenticated
  USING (account_id = (SELECT auth.uid())
         AND (SELECT folioone.persona_write_rpc_context()))
  WITH CHECK (account_id = (SELECT auth.uid())
              AND (SELECT folioone.persona_write_rpc_context()));
CREATE POLICY personas_delete_rpc_own ON folioone.personas
  FOR DELETE TO authenticated
  USING (account_id = (SELECT auth.uid())
         AND (SELECT folioone.persona_write_rpc_context()));

-- persona_sections (no DELETE: P-5)
CREATE POLICY persona_sections_select_own ON folioone.persona_sections
  FOR SELECT TO authenticated USING (account_id = (SELECT auth.uid()));
CREATE POLICY persona_sections_insert_rpc_own ON folioone.persona_sections
  FOR INSERT TO authenticated
  WITH CHECK (account_id = (SELECT auth.uid())
              AND (SELECT folioone.persona_write_rpc_context()));
CREATE POLICY persona_sections_update_rpc_own ON folioone.persona_sections
  FOR UPDATE TO authenticated
  USING (account_id = (SELECT auth.uid())
         AND (SELECT folioone.persona_write_rpc_context()))
  WITH CHECK (account_id = (SELECT auth.uid())
              AND (SELECT folioone.persona_write_rpc_context()));

-- persona_profile_field_selections (no DELETE)
CREATE POLICY persona_profile_field_selections_select_own
  ON folioone.persona_profile_field_selections
  FOR SELECT TO authenticated USING (account_id = (SELECT auth.uid()));
CREATE POLICY persona_profile_field_selections_insert_rpc_own
  ON folioone.persona_profile_field_selections
  FOR INSERT TO authenticated
  WITH CHECK (account_id = (SELECT auth.uid())
              AND (SELECT folioone.persona_write_rpc_context()));
CREATE POLICY persona_profile_field_selections_update_rpc_own
  ON folioone.persona_profile_field_selections
  FOR UPDATE TO authenticated
  USING (account_id = (SELECT auth.uid())
         AND (SELECT folioone.persona_write_rpc_context()))
  WITH CHECK (account_id = (SELECT auth.uid())
              AND (SELECT folioone.persona_write_rpc_context()));

-- persona_profile_overrides (DELETE is used by "reset to My Identity")
CREATE POLICY persona_profile_overrides_select_own
  ON folioone.persona_profile_overrides
  FOR SELECT TO authenticated USING (account_id = (SELECT auth.uid()));
CREATE POLICY persona_profile_overrides_insert_rpc_own
  ON folioone.persona_profile_overrides
  FOR INSERT TO authenticated
  WITH CHECK (account_id = (SELECT auth.uid())
              AND (SELECT folioone.persona_write_rpc_context()));
CREATE POLICY persona_profile_overrides_update_rpc_own
  ON folioone.persona_profile_overrides
  FOR UPDATE TO authenticated
  USING (account_id = (SELECT auth.uid())
         AND (SELECT folioone.persona_write_rpc_context()))
  WITH CHECK (account_id = (SELECT auth.uid())
              AND (SELECT folioone.persona_write_rpc_context()));
CREATE POLICY persona_profile_overrides_delete_rpc_own
  ON folioone.persona_profile_overrides
  FOR DELETE TO authenticated
  USING (account_id = (SELECT auth.uid())
         AND (SELECT folioone.persona_write_rpc_context()));

-- persona_revisions: append-only. SELECT, plus INSERT where the actor is the caller.
CREATE POLICY persona_revisions_select_own ON folioone.persona_revisions
  FOR SELECT TO authenticated USING (account_id = (SELECT auth.uid()));
CREATE POLICY persona_revisions_insert_rpc_own ON folioone.persona_revisions
  FOR INSERT TO authenticated
  WITH CHECK (account_id = (SELECT auth.uid())
              AND actor_id = (SELECT auth.uid())
              AND (SELECT folioone.persona_write_rpc_context()));

-- 3. Grants: SELECT table-wide (RLS limits rows); writes column-level ----------
-- 001 left these tables with no privileges at all, so these are the only ones.
GRANT SELECT ON TABLE folioone.personas, folioone.persona_sections,
  folioone.persona_profile_field_selections, folioone.persona_profile_overrides,
  folioone.persona_revisions TO authenticated;

GRANT INSERT (account_id, name, slug, description, audience, purpose, position)
  ON folioone.personas TO authenticated;
GRANT UPDATE (name, slug, description, audience, purpose, status, is_default,
              version, updated_at, archived_at)
  ON folioone.personas TO authenticated;
GRANT DELETE ON folioone.personas TO authenticated;

GRANT INSERT (persona_id, account_id, section_key, label_override, is_visible, position)
  ON folioone.persona_sections TO authenticated;
GRANT UPDATE (label_override, is_visible, position, updated_at)
  ON folioone.persona_sections TO authenticated;

GRANT INSERT (persona_id, account_id, field_key, is_included, position, is_highlighted)
  ON folioone.persona_profile_field_selections TO authenticated;
GRANT UPDATE (is_included, position, is_highlighted, updated_at)
  ON folioone.persona_profile_field_selections TO authenticated;

GRANT INSERT (persona_id, account_id, field_key, override_value)
  ON folioone.persona_profile_overrides TO authenticated;
GRANT UPDATE (override_value, override_version, updated_at)
  ON folioone.persona_profile_overrides TO authenticated;
GRANT DELETE ON folioone.persona_profile_overrides TO authenticated;

GRANT INSERT (persona_id, account_id, actor_id, revision_number, event_type,
              configuration_payload)
  ON folioone.persona_revisions TO authenticated;

-- 4. Assert the outcome before committing --------------------------------------
DO $assert$
DECLARE
  expected_paths text[] := ARRAY[
    '/rpc/persona_create_with_configuration', '/rpc/persona_update_metadata',
    '/rpc/persona_apply_profile_field_changes', '/rpc/persona_upsert_section',
    '/rpc/persona_reorder_sections', '/rpc/persona_set_default',
    '/rpc/persona_set_lifecycle', '/rpc/persona_duplicate', '/rpc/persona_delete'];
  definition text;
  path text;
  bad text;
BEGIN
  SELECT string_agg(t || '=' || n, ', ') INTO bad
  FROM (SELECT tablename AS t, count(*)::text AS n FROM pg_policies
        WHERE schemaname = 'folioone' GROUP BY tablename) AS counts
  WHERE (t, n) NOT IN (('personas', '4'), ('persona_sections', '3'),
    ('persona_profile_field_selections', '3'), ('persona_profile_overrides', '4'),
    ('persona_revisions', '2'))
    AND t IN ('personas', 'persona_sections', 'persona_profile_field_selections',
              'persona_profile_overrides', 'persona_revisions');
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'Unexpected policy counts: %', bad;
  END IF;
  IF (SELECT count(*) FROM pg_policies WHERE schemaname = 'folioone'
      AND tablename IN ('personas', 'persona_sections',
        'persona_profile_field_selections', 'persona_profile_overrides',
        'persona_revisions')) <> 16 THEN
    RAISE EXCEPTION 'Expected exactly 16 Persona policies';
  END IF;
  IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'folioone'
             AND tablename LIKE 'persona%' AND NOT ('authenticated' = ANY (roles))) THEN
    RAISE EXCEPTION 'Every Persona policy must target authenticated only';
  END IF;

  SELECT pg_get_functiondef('folioone.persona_write_rpc_context()'::regprocedure) INTO definition;
  FOREACH path IN ARRAY expected_paths LOOP
    IF position(quote_literal(path) IN definition) = 0 THEN
      RAISE EXCEPTION 'Gate allowlist is missing %', path;
    END IF;
  END LOOP;
  IF definition ~* '\mLIKE\M|~|\|\|' THEN
    RAISE EXCEPTION 'Gate must use exact equality only';
  END IF;

  FOR bad IN
    SELECT c.relname FROM pg_class AS c JOIN pg_namespace AS n ON n.oid = c.relnamespace
    WHERE n.nspname = 'folioone' AND c.relname IN ('personas', 'persona_sections',
      'persona_profile_field_selections', 'persona_profile_overrides', 'persona_revisions')
      AND (has_table_privilege('authenticated', c.oid, 'INSERT')
        OR has_table_privilege('authenticated', c.oid, 'UPDATE')
        OR has_table_privilege('authenticated', c.oid, 'TRUNCATE')
        OR has_table_privilege('authenticated', c.oid, 'REFERENCES')
        OR has_table_privilege('authenticated', c.oid, 'TRIGGER'))
  LOOP
    RAISE EXCEPTION 'authenticated holds a table-wide write privilege on %', bad;
  END LOOP;
  FOR bad IN
    SELECT c.relname FROM pg_class AS c JOIN pg_namespace AS n ON n.oid = c.relnamespace
    WHERE n.nspname = 'folioone' AND c.relname IN ('personas', 'persona_sections',
      'persona_profile_field_selections', 'persona_profile_overrides', 'persona_revisions')
      AND (has_any_column_privilege('anon', c.oid, 'SELECT,INSERT,UPDATE,REFERENCES')
        OR has_any_column_privilege('service_role', c.oid, 'SELECT,INSERT,UPDATE,REFERENCES')
        OR has_table_privilege('anon', c.oid, 'DELETE')
        OR has_table_privilege('service_role', c.oid, 'DELETE'))
  LOOP
    RAISE EXCEPTION 'anon or service_role holds a privilege on %', bad;
  END LOOP;
  IF EXISTS (SELECT 1 FROM pg_class AS c JOIN pg_namespace AS n ON n.oid = c.relnamespace
             CROSS JOIN LATERAL aclexplode(COALESCE(c.relacl, acldefault('r', c.relowner))) AS a
             WHERE n.nspname = 'folioone' AND c.relname LIKE 'persona%' AND a.grantee = 0) THEN
    RAISE EXCEPTION 'PUBLIC holds a privilege on a Persona table';
  END IF;
  -- DELETE only on personas and persona_profile_overrides.
  IF (SELECT array_agg(c.relname ORDER BY c.relname) FROM pg_class AS c
      JOIN pg_namespace AS n ON n.oid = c.relnamespace
      WHERE n.nspname = 'folioone' AND c.relname LIKE 'persona%'
        AND c.relkind = 'r' AND has_table_privilege('authenticated', c.oid, 'DELETE'))
     IS DISTINCT FROM ARRAY['persona_profile_overrides', 'personas']::name[] THEN
    RAISE EXCEPTION 'authenticated DELETE must be limited to personas and persona_profile_overrides';
  END IF;
END;
$assert$;

COMMIT;

